<?php
require_once __DIR__.'/../includes/auth.php'; require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)$_POST['booking_id'];$action=$_POST['action'];$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT b.*,e.available_quantity,e.condition_status,e.name equipment_name FROM bookings b JOIN equipment e ON e.id=b.equipment_id WHERE b.id=? FOR UPDATE");$s->execute([$id]);$b=$s->fetch();if(!$b)throw new Exception('Booking not found.');
 if($action==='approve' && $b['status']==='Pending'){if($b['condition_status']==='Under Maintenance')throw new Exception('Equipment is under maintenance.');$q=$pdo->prepare("SELECT COALESCE(SUM(quantity),0) FROM bookings WHERE equipment_id=? AND status='Approved' AND booking_date=? AND start_time < ? AND end_time > ?");$q->execute([$b['equipment_id'],$b['booking_date'],$b['end_time'],$b['start_time']]);$reserved=(int)$q->fetchColumn();$total=(int)$pdo->query("SELECT quantity FROM equipment WHERE id=".(int)$b['equipment_id'])->fetchColumn();if($total-$reserved<(int)$b['quantity'])throw new Exception('Not enough quantity for this time slot.');$pdo->prepare("UPDATE bookings SET status='Approved' WHERE id=?")->execute([$id]);}
 elseif(in_array($action,['reject','complete','cancel'],true)){$new=['reject'=>'Rejected','complete'=>'Completed','cancel'=>'Cancelled'][$action];$pdo->prepare("UPDATE bookings SET status=? WHERE id=?")->execute([$new,$id]);}
 $pdo->commit();notify($pdo,(int)$b['student_user_id'],'Your booking #'.$id.' status is now updated.');flash('Booking updated.');
 }catch(Throwable $e){$pdo->rollBack();flash($e->getMessage(),'danger');}redirect('bookings.php');}
$rows=$pdo->query("SELECT b.*,u.name student,e.name equipment_name,s.student_id FROM bookings b JOIN users u ON u.id=b.student_user_id JOIN equipment e ON e.id=b.equipment_id LEFT JOIN students s ON s.user_id=u.id ORDER BY b.created_at DESC")->fetchAll();page_header('Booking Management','admin');?>
<div class="panel"><h2 class="section-title">All booking requests</h2><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Booking</th><th>Student</th><th>Equipment</th><th>Quantity</th><th>Date / Time</th><th>Purpose</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td>#<?=$r['id']?></td><td><?=e($r['student'])?><br><small class="muted"><?=e($r['student_id'])?></small></td><td><?=e($r['equipment_name'])?></td><td><?=$r['quantity']?></td><td><?=e($r['booking_date'])?><br><?=e(substr($r['start_time'],0,5))?>–<?=e(substr($r['end_time'],0,5))?></td><td><?=e($r['purpose'])?></td><td><?=status_badge($r['status'])?></td><td><div class="inline-actions"><?php foreach(['approve'=>'Approve','reject'=>'Reject','complete'=>'Complete','cancel'=>'Cancel'] as $a=>$label):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="booking_id" value="<?=$r['id']?>"><button class="btn btn-sm btn-outline-light" name="action" value="<?=$a?>"><?=$label?></button></form><?php endforeach?></div></td></tr><?php endforeach?></tbody></table></div></div><?php page_footer();?>
